const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hash=s=>{let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0).toString(36)};
async function submit(path,data,key){const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key},body:JSON.stringify(data)});const b=await r.json();if(!r.ok)throw new Error(b.error||'تعذر إرسال الطلب. حاولي مجددًا.');return b}
function prepareForm(form,path,read,onSuccess){if(!form)return;let key=crypto.randomUUID(),last=null,busy=false;const honey=document.createElement('input');honey.name='website';honey.tabIndex=-1;honey.autocomplete='off';honey.setAttribute('aria-hidden','true');honey.style.cssText='position:absolute;width:1px;height:1px;opacity:0;overflow:hidden;clip-path:inset(50%);pointer-events:none';form.append(honey);const feedback=document.createElement('p');feedback.setAttribute('role','status');feedback.className='form-note';form.after(feedback);form.addEventListener('submit',async e=>{e.preventDefault();if(busy||!form.reportValidity())return;const value=read(form);if(!value)return;value.website=honey.value;const serialized=JSON.stringify(value);if(last!==null&&last!==serialized)key=crypto.randomUUID();last=serialized;busy=true;const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;feedback.textContent='جارٍ إرسال طلبكِ…';try{const result=await submit(path,value,key);feedback.textContent='';onSuccess(result,value);key=crypto.randomUUID();last=null;form.reset()}catch(err){feedback.textContent=err.message;feedback.style.color='#9b392f'}finally{busy=false;if(button)button.disabled=false}})}
export async function enhanceSite(data,page,dressId){const s=data.settings;document.documentElement.style.setProperty('--gold',s.gold);document.documentElement.style.setProperty('--ivory',s.background);document.documentElement.style.setProperty('--ink',s.ink);if(page==='home')document.title=s.seoTitle;const meta=document.querySelector('meta[name="description"]');if(meta)meta.content=s.seoDescription;
 const details=document.querySelector('.contact-details');if(details)details.innerHTML=`<p>${esc(s.address)}</p>${s.phone?`<a dir="ltr" href="tel:+${s.phone}">+${s.phone}</a><a class="btn whatsapp" href="https://wa.me/${s.phone}" target="_blank" rel="noopener">تواصلي عبر واتساب</a>`:''}${s.email?`<a href="mailto:${esc(s.email)}">${esc(s.email)}</a>`:''}<p>${esc(s.hours)}</p>`;
 const map=document.querySelector('.map');if(map){map.src='https://maps.google.com/maps?q='+encodeURIComponent(s.mapQuery)+'&output=embed';map.title='موقع المعرض: '+s.address}
 const aside=document.querySelector('.form-aside p');if(aside)aside.textContent=s.address+' · '+s.hours;
 const price=document.querySelector('#price-whatsapp');if(price&&!s.phone){price.href='contact.html';price.removeAttribute('target');price.textContent='تواصلي مع المعرض للاستفسار'}
 const d=data.dresses.find(x=>x.id===dressId);if(page==='detail'&&d){const names={white:'أبيض',ivory:'عاجي',champagne:'شامبين',pink:'وردي فاتح'};document.querySelectorAll('[data-color]').forEach(el=>{const key=Object.keys(names).find(k=>names[k]===el.dataset.color);if(!d.colors.includes(key))el.remove();else el.setAttribute('aria-pressed',String(key===d.color))});document.querySelector('#selected-color').textContent=names[d.color];document.querySelectorAll('[data-size]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.size)===d.sizes[0])));if(!s.phone){document.querySelectorAll('[data-color],[data-size]').forEach(el=>el.addEventListener('click',()=>{price.href='contact.html'}))}}
 const booking=document.querySelector('#booking-form');if(booking){const today=new Date(Date.now()+10800000).toISOString().slice(0,10);booking.querySelectorAll('[type=date]').forEach(el=>el.min=today);booking.elements.dress.value=new URLSearchParams(location.search).get('dress')||'';booking.elements.time.innerHTML='<option value="">اختاري الوقت</option>'+Array.from({length:s.closeTime-s.openTime},(_,i)=>String(i+s.openTime).padStart(2,'0')+':00').map(t=>`<option>${t}</option>`).join('');booking.elements.service.innerHTML=s.services.map(x=>`<option>${esc(x)}</option>`).join('');const validate=()=>{const el=booking.elements.date,value=el.value;el.setCustomValidity(value&&(s.closedDays.includes(new Date(value+'T12:00:00Z').getUTCDay())||s.blockedDates.includes(value))?'المعرض مغلق في هذا اليوم. اختاري يومًا آخر.':booking.elements.wedding.value&&value>booking.elements.wedding.value?'اختاري موعد زيارة قبل الزفاف.':'')};booking.elements.date.onchange=validate;booking.elements.wedding.onchange=validate;if(!s.bookingEnabled){booking.querySelectorAll('input,select,textarea,button').forEach(x=>x.disabled=true);booking.insertAdjacentHTML('beforebegin','<div class="success-panel">استقبال الحجوزات متوقف مؤقتًا. يسعدنا تواصلكِ عبر صفحة التواصل.</div>')}prepareForm(booking,'bookings',form=>{validate();if(!form.reportValidity())return null;return Object.fromEntries(new FormData(form))},result=>{const box=document.querySelector('#booking-result');box.hidden=false;box.className='success-panel';box.innerHTML=`<h3>وصل طلب موعدكِ ✧</h3><p>سيُراجع فريق المعرض طلبكِ ويتواصل معكِ لتأكيد الموعد.</p><p class="small-text">رقم الطلب: ${esc(result.id)}</p>`;box.scrollIntoView({block:'center',behavior:'smooth'})})}
 prepareForm(document.querySelector('#contact-form'),'messages',form=>Object.fromEntries(new FormData(form)),result=>{document.querySelector('#contact-result').innerHTML=`<div class="success-panel"><h3>وصلت رسالتكِ</h3><p>سيطّلع عليها فريق المعرض. شكرًا لتواصلكِ.</p><p class="small-text">رقم الرسالة: ${esc(result.id)}</p></div>`});
 prepareForm(document.querySelector('.newsletter'),'subscribers',form=>({email:form.querySelector('[type=email]').value}),()=>{const t=document.querySelector('#toast');t.textContent='تم تسجيل اشتراككِ بنجاح';t.hidden=false;setTimeout(()=>t.hidden=true,5000)});
 const nodes=new Map(),sections=[...document.querySelectorAll('#main > section')];const walker=document.createTreeWalker(document.querySelector('#app'),NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const parent=node.parentElement;if(!parent||parent.closest('script,style,svg,option,button,.dress-card,.designer-card,.collection-card,.detail-info,.viewer,.thumbnails,.form-note,.contact-details,.stat strong'))continue;const original=node.nodeValue;if(original.trim().length<3||!/[\p{L}]/u.test(original))continue;const scope=parent.closest('header,footer,.announcement')?'shared':page,key=hash(original.trim());const item={type:'text',key,scope,original,text:original,nodes:[]};if(!nodes.has(scope+':'+key))nodes.set(scope+':'+key,item);nodes.get(scope+':'+key).nodes.push(node);const value=data.pages[scope]?.[key];if(value!==undefined)node.nodeValue=value;}
 document.querySelectorAll('#app img').forEach(img=>{const original=img.dataset.cmsOriginal||new URL(img.getAttribute('src'),location.href).pathname;img.dataset.cmsOriginal=original;if(data.imageOverrides[original])img.src=data.imageOverrides[original]});
 const edit=new URLSearchParams(location.search).get('cms')==='1'&&window.parent!==window;
 if(!edit){for(const i of data.hiddenSections[page]||[])if(sections[i])sections[i].hidden=true;return}
 const check=await fetch('/api/admin/me');if(!check.ok)return;const user=await check.json();if(!['owner','editor'].includes(user.role))return;
 const style=document.createElement('style');style.textContent='[data-cms-hover]{outline:2px dashed #ae8b48!important;outline-offset:3px;cursor:pointer!important}';document.head.append(style);
 const sectionInfo=sections.map((el,index)=>({index,title:el.querySelector('h1,h2,h3')?.textContent.trim().slice(0,60)||'قسم '+(index+1)}));
 const send=msg=>window.parent.postMessage(msg,location.origin);send({type:'cms-ready',sections:sectionInfo});
 let hovered;document.addEventListener('pointerover',e=>{hovered?.removeAttribute('data-cms-hover');hovered=e.target.closest('img,h1,h2,h3,p,span,li,a,strong,small,cite,blockquote');hovered?.setAttribute('data-cms-hover','')});
 document.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();const img=e.target.closest('img');if(img){send({type:'cms-select',item:{type:'image',original:img.dataset.cmsOriginal}});return}const item=[...nodes.values()].find(item=>item.nodes.some(n=>n.parentElement===e.target||e.target.contains(n.parentElement)));if(item)send({type:'cms-select',item:{type:'text',key:item.key,scope:item.scope,original:item.original,text:item.nodes[0].nodeValue}})},true);
 addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==window.parent||e.data?.type!=='cms-change')return;const {item,value}=e.data;if(typeof value!=='string')return;if(item.type==='text'){const entry=nodes.get(item.scope+':'+item.key);entry?.nodes.forEach(n=>n.nodeValue=value)}else if(/^\/(images|media)\/[\w.-]+$/.test(value))document.querySelectorAll('img').forEach(img=>{if(img.dataset.cmsOriginal===item.original)img.src=value})});
}
